value.outputSchema:
={{ {
  "type": "object",
  "required": ["posts"],
  "properties": {
    "posts": {
      "type": "array",
      "description": "Every distinct hiring post found, written by an individual (not a company page).",
      "items": {
        "type": "object",
        "required": [
          "post_url",
          "post_id",
          "poster_name",
          "poster_profile_url",
          "post_text"
        ],
        "properties": {
          "post_url": {
            "type": "string",
            "description": "Exact LinkedIn post URL.",
            "nimbus_rules": ["url", "max:2000"]
          },
          "post_id": {
            "type": "string",
            "description": "Digits-only activity ID parsed from post_url.",
            "nimbus_rules": ["min:1", "max:50", "in:digits_only"]
          },
          "poster_name": {
            "type": "string",
            "description": "Poster's display name.",
            "nimbus_rules": ["min:1", "max:200"]
          },
          "poster_profile_url": {
            "type": "string",
            "description": "Poster's own /in/<username>/ profile URL (not the post URL).",
            "nimbus_rules": ["url", "max:500"]
          },
          "post_text": {
            "type": "string",
            "description": "The post body text.",
            "nimbus_rules": ["min:1", "max:50000"]
          }
        }
      },
      "nimbus_rules": ["min:1"]
    }
  }
}
 }}
